<?php

tutorpress_live_lessons_assert( class_exists( 'TutorPress_Live_Lesson_Datetime' ), 'datetime class is loaded' );
tutorpress_live_lessons_assert( TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-09-21 15:04:00' ) && TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-02-31 00:00:00' ), 'minute-precision wall clock is accepted' );
tutorpress_live_lessons_assert( ! TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-09-21 15:04:01' ) && ! TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-09-21T15:04:00' ) && ! TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-09-21 15:04' ) && ! TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-13-01 00:00:00' ), 'non-minute wall-clock forms are rejected' );
tutorpress_live_lessons_assert( TutorPress_Live_Lesson_Datetime::is_approved_timezone( 'UTC' ) && TutorPress_Live_Lesson_Datetime::is_approved_timezone( 'America/New_York' ) && TutorPress_Live_Lesson_Datetime::is_approved_timezone( 'US/Eastern' ), 'UTC and ALL_WITH_BC identifiers are accepted' );
tutorpress_live_lessons_assert( ! TutorPress_Live_Lesson_Datetime::is_approved_timezone( 'utc' ) && ! TutorPress_Live_Lesson_Datetime::is_approved_timezone( 'SST' ) && ! TutorPress_Live_Lesson_Datetime::is_approved_timezone( 'Z' ), 'aliases outside the approved set are rejected' );
$ny  = TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-09-21 15:04:00', 'America/New_York' );
$utc = TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-09-21 15:04:00', 'UTC' );
tutorpress_live_lessons_assert( $ny instanceof DateTimeImmutable && $utc instanceof DateTimeImmutable && '2026-09-21 15:04:00' === $ny->format( 'Y-m-d H:i:s' ) && '2026-09-21 15:04:00' === $utc->format( 'Y-m-d H:i:s' ) && $ny->getTimestamp() !== $utc->getTimestamp(), 'parsed wall clock round-trips in its timezone' );
tutorpress_live_lessons_assert( null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-02-31 00:00:00', 'UTC' ) && TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-02-31 00:00:00' ) && null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-09-21 15:04:01', 'UTC' ) && null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-09-21 15:04:00', 'utc' ), 'normalization and unapproved input do not parse' );
tutorpress_live_lessons_assert( null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-03-08 02:30:00', 'America/New_York' ) && null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-11-01 01:30:00', 'America/New_York' ), 'spring gaps and fallback folds are rejected' );
$before = TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-03-08 01:30:00', 'America/New_York' );
$after  = TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-11-01 02:30:00', 'America/New_York' );
tutorpress_live_lessons_assert( $before instanceof DateTimeImmutable && $after instanceof DateTimeImmutable && '2026-03-08 01:30:00' === $before->format( 'Y-m-d H:i:s' ) && '2026-11-01 02:30:00' === $after->format( 'Y-m-d H:i:s' ), 'unique instants beside a gap and a fold are kept' );
tutorpress_live_lessons_assert( TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-09-21 23:00:00', '2026-09-22 01:00:00', 'America/New_York' ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-09-22 01:00:00', '2026-09-21 23:00:00', 'America/New_York' ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-09-21 15:04:00', '2026-09-21 15:04:00', 'UTC' ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-03-08 02:30:00', '2026-03-08 03:30:00', 'America/New_York' ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-11-01 01:30:00', '2026-11-01 02:30:00', 'America/New_York' ), 'google ordering uses unique instants' );
$hours = TutorPress_Live_Lesson_Datetime::zoom_duration( 8, 'hours' );
tutorpress_live_lessons_assert( array( 'value' => 8, 'unit' => 'hours' ) === $hours && array( 'value' => 480, 'unit' => 'minutes' ) === TutorPress_Live_Lesson_Datetime::zoom_duration( 480, 'minutes' ) && null === TutorPress_Live_Lesson_Datetime::zoom_duration( 9, 'hours' ) && null === TutorPress_Live_Lesson_Datetime::zoom_duration( 481, 'minutes' ) && null === TutorPress_Live_Lesson_Datetime::zoom_duration( 8, 'min' ), 'zoom duration retains its unit' );
tutorpress_live_lessons_assert( ! TutorPress_Live_Lesson_Datetime::is_wall_clock( '' ) && ! TutorPress_Live_Lesson_Datetime::is_wall_clock( null ) && ! TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-09-21T15:04:00-04:00' ) && ! TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-09-21 24:00:00' ) && TutorPress_Live_Lesson_Datetime::is_wall_clock( '2026-04-31 00:00:00' ) && null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-04-31 00:00:00', 'UTC' ), 'malformed and impossible dates do not parse' );
tutorpress_live_lessons_assert( null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-03-08 02:00:00', 'America/New_York' ) && null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-03-08 02:59:00', 'America/New_York' ), 'the whole spring gap is rejected' );
tutorpress_live_lessons_assert( null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-11-01 01:00:00', 'America/New_York' ) && null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-11-01 01:59:00', 'America/New_York' ), 'the whole fallback fold is rejected' );
$after_gap   = TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-03-08 03:30:00', 'America/New_York' );
$before_fold = TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-11-01 00:30:00', 'America/New_York' );
tutorpress_live_lessons_assert( $after_gap instanceof DateTimeImmutable && $before_fold instanceof DateTimeImmutable && -14400 === $after_gap->getOffset() && -14400 === $before_fold->getOffset() && '2026-03-08 03:30:00' === $after_gap->format( 'Y-m-d H:i:s' ) && '2026-11-01 00:30:00' === $before_fold->format( 'Y-m-d H:i:s' ), 'unique instants on the other side of each transition are kept' );
tutorpress_live_lessons_assert( TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-03-07 23:00:00', '2026-03-08 03:30:00', 'America/New_York' ) && TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-10-31 23:30:00', '2026-11-01 00:30:00', 'America/New_York' ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-10-31 23:00:00', '2026-11-01 01:30:00', 'America/New_York' ), 'overnight ranges resolve only when both instants are unique' );
tutorpress_live_lessons_assert( TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-03-08 01:30:00', '2026-03-08 03:30:00', 'America/New_York' ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-03-08 03:30:00', '2026-03-08 01:30:00', 'America/New_York' ) && TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-11-01 00:30:00', '2026-11-01 02:30:00', 'America/New_York' ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-03-08 01:30:00', '2026-03-08 02:30:00', 'America/New_York' ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-11-01 00:30:00', '2026-11-01 01:30:00', 'America/New_York' ), 'ordering across a gap or fold uses only unique instants' );
tutorpress_live_lessons_assert( array( 'value' => 1, 'unit' => 'minutes' ) === TutorPress_Live_Lesson_Datetime::zoom_duration( 1, 'minutes' ) && array( 'value' => 1, 'unit' => 'hours' ) === TutorPress_Live_Lesson_Datetime::zoom_duration( 1, 'hours' ) && null === TutorPress_Live_Lesson_Datetime::zoom_duration( 0, 'minutes' ) && null === TutorPress_Live_Lesson_Datetime::zoom_duration( 8, 'hr' ) && null === TutorPress_Live_Lesson_Datetime::zoom_duration( '8', 'hours' ) && null === TutorPress_Live_Lesson_Datetime::zoom_duration( 8, '' ), 'duration bounds and legacy unit tokens stay typed' );
tutorpress_live_lessons_assert( ! TutorPress_Live_Lesson_Datetime::is_approved_timezone( '' ) && ! TutorPress_Live_Lesson_Datetime::is_approved_timezone( null ) && null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-09-21 15:04:00', '' ) && null === TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-09-21 15:04:00', null ) && ! TutorPress_Live_Lesson_Datetime::google_end_after_start( '2026-09-21 15:00:00', '2026-09-21 16:00:00', '' ), 'a missing zone does not parse' );
$default_zone = date_default_timezone_get();
date_default_timezone_set( 'America/New_York' );
$legacy_fold  = TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-11-01 01:30:00', 'America/New_York' );
$explicit_utc = TutorPress_Live_Lesson_Datetime::parse_wall_clock( '2026-11-01 01:30:00', 'UTC' );
date_default_timezone_set( $default_zone );
tutorpress_live_lessons_assert( null === $legacy_fold && $explicit_utc instanceof DateTimeImmutable && '2026-11-01 01:30:00' === $explicit_utc->format( 'Y-m-d H:i:s' ) && 'UTC' === $explicit_utc->getTimezone()->getName(), 'legacy ambiguity requests explicit correction' );
$site_zone = date_default_timezone_get();
date_default_timezone_set( 'UTC' );
$between      = new DateTimeImmutable( '2026-09-21 16:00:00', new DateTimeZone( 'UTC' ) );
$exact        = new DateTimeImmutable( '2026-09-21 19:04:00', new DateTimeZone( 'UTC' ) );
$spring       = new DateTimeImmutable( '2026-03-08 07:00:00', new DateTimeZone( 'UTC' ) );
$fall         = new DateTimeImmutable( '2026-11-01 06:00:00', new DateTimeZone( 'UTC' ) );
$zone_differs = TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-09-21 15:04:00', 'America/New_York', $between ) && ! TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-09-21 15:04:00', 'UTC', $between ) && ! TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-09-21 15:04:00', 'America/New_York', $exact );
$spring_edge  = ! TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-03-08 01:30:00', 'America/New_York', $spring ) && TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-03-08 03:30:00', 'America/New_York', $spring ) && ! TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-03-08 02:30:00', 'America/New_York', $spring );
$fall_edge    = ! TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-11-01 00:30:00', 'America/New_York', $fall ) && TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-11-01 02:30:00', 'America/New_York', $fall ) && ! TutorPress_Live_Lesson_Datetime::is_future_wall_clock( '2026-11-01 01:30:00', 'America/New_York', $fall );
date_default_timezone_set( $site_zone );
tutorpress_live_lessons_assert( $zone_differs, 'selected zone differs from the site zone' );
tutorpress_live_lessons_assert( $spring_edge, 'spring transition-adjacent instants compare by the injected clock' );
tutorpress_live_lessons_assert( $fall_edge, 'fallback transition-adjacent instants compare by the injected clock' );
tutorpress_live_lessons_pass( 'datetime ordering and typed zoom duration' );
